const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const plumePoint = ee.Geometry.Point([-136.275745, 69.264212]);
  const oceanPoint = ee.Geometry.Point([-137.786365, 69.803894]);
  const date = '2017-07-19';
  const dateStart = ee.Date(date);
  const dateEnd = dateStart.advance(1, 'day');

  // Buffer points for sampling
  const plumeRegion = plumePoint.buffer(500);
  const oceanRegion = oceanPoint.buffer(500);

  // 2. Data Acquisition - Try Sentinel-2 first
  let collection = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(dateStart, dateEnd)
    .filterBounds(plumePoint.union(oceanPoint));

  let collSize = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collSize}`);

  // Fallback to Landsat 8 if no Sentinel-2
  if (collSize === 0) {
    console.log('Trying Landsat 8...');
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(dateStart, dateEnd)
      .filterBounds(plumePoint.union(oceanPoint));
    collSize = collection.size().getInfo();
    console.log(`Landsat 8 images found: ${collSize}`);
  }

  if (collSize === 0) {
    console.log('No images available for this date and location.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing
  let image;
  if (collection.first().bandNames().getInfo().includes('B4')) {
    // Sentinel-2
    image = collection.first().select(['B2', 'B3', 'B4']); // Blue, Green, Red
  } else {
    // Landsat 8
    image = collection.first().select(['SR_B2', 'SR_B3', 'SR_B4']); // Blue, Green, Red
  }

  // Calculate mean reflectance for turbidity assessment
  const plumeStats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: plumeRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const oceanStats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: oceanRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  console.log('Plume stats:', JSON.stringify(plumeStats));
  console.log('Ocean stats:', JSON.stringify(oceanStats));

  // Get band names (different for Sentinel-2 and Landsat)
  const bands = Object.keys(plumeStats).filter(k => k.includes('mean'));

  if (bands.length === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check pixel counts
  const countKey = Object.keys(plumeStats).find(k => k.includes('count'));
  const plumeCount = plumeStats[countKey];
  const oceanCount = oceanStats[countKey];

  if (plumeCount === 0 || oceanCount === 0) {
    console.log(`Pixel counts - Plume: ${plumeCount}, Ocean: ${oceanCount}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Average reflectance across visible bands
  let plumeReflectance = 0;
  let oceanReflectance = 0;

  for (const band of bands) {
    const plumeVal = plumeStats[band];
    const oceanVal = oceanStats[band];

    if (plumeVal == null || oceanVal == null || isNaN(plumeVal) || isNaN(oceanVal)) {
      console.log('Calculation failed: null or NaN values.');
      console.log('<answer>C3</answer>');
      return;
    }

    plumeReflectance += plumeVal;
    oceanReflectance += oceanVal;
  }

  plumeReflectance /= bands.length;
  oceanReflectance /= bands.length;

  // 5. Validation & Final Answer
  console.log(`Plume avg reflectance: ${plumeReflectance.toFixed(2)}, Pixels: ${plumeCount}`);
  console.log(`Ocean avg reflectance: ${oceanReflectance.toFixed(2)}, Pixels: ${oceanCount}`);

  // Milky appearance means higher reflectance (more turbid/sediment-laden)
  const difference = plumeReflectance - oceanReflectance;
  console.log(`Difference (plume - ocean): ${difference.toFixed(2)}`);

  if (difference > 100) {  // Threshold for "more milky"
    console.log('Plume appears more milky than open ocean.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Plume does not appear significantly more milky.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
